head.script:
scwin.floatingLayer1_headerHTML = function() {
    var ret = "";
    switch (scwin.condition) {
        case 1:
            ret = "<span> test1 </span>";
            break;
        case 2:
            ret = "<span> test2 </span>";
            break;
        default:
            ret = "<span> test </span>";
            break;
    }
    return ret;
}
scwin.trigger1_onclick = function(e) {
    scwin.condition = 1;
    floatingLayer1.setHeaderHTML(scwin.floatingLayer1_headerHTML);
};
scwin.trigger2_onclick = function(e) {
    scwin.condition = 2;
    floatingLayer1.setHeaderHTML(scwin.floatingLayer1_headerHTML);
};
scwin.checktype1 = function() {
    return typeof WebSquare.wUnit.getDomById('floatingLayer1_headerHTML') == 'object' && WebSquare.wUnit.getDomById('floatingLayer1_headerHTML').innerText.trim() == 'test1';
}
scwin.checktype2 = function() {
    return typeof WebSquare.wUnit.getDomById('loatingLayer1_headerHTML') == 'object' && WebSquare.wUnit.getDomById('floatingLayer1_headerHTML').innerText.trim() == 'test2';
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    //Test step 1. 1번의 샘플파일을 실행 후 headerHTML1 버튼을 클릭한다.
    //1. Run sample file 1 and click the headerHTML1 button.
    WebSquare.wUnit.addCommand("pause", "100");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "100");
    //Verify step 1. 타이틀이 test1으로 변경된다.
    //1. The title is changed to test1.
    WebSquare.wUnit.addCommand("assert", "scwin.checktype1()", "true");
    WebSquare.wUnit.addCommand("pause", "100");
    //Test step 2. headerHTML2 버튼을 클릭한다.
    //2. Click the headerHTML2 button.
    WebSquare.wUnit.addCommand("pause", "100");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger2').click()");
    WebSquare.wUnit.addCommand("pause", "100");
    //Verify step 2. test2로 변경된다.
    //2. Change to test2.
    WebSquare.wUnit.addCommand("assert", "scwin.checktype2()", "true");
    WebSquare.wUnit.addCommand("pause", "100");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    scwin.condition = 0;
    scwin.floatingLayer2_headerHTML = "<span> floatingLayer_2 </span>";
    //Function 
    //Created by: Quan.Nguyen
    //Created date: 28-Mar-2018
    //end
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
